// Allocate a fresh SHA1_INFO context and initialize it for a new computation.
// The struct is user-managed storage; we create it here and return ownership to the pool.
SHA1_INFO *sha1_info = new SHA1_INFO();
// Initialize the context in-place.
sha1_init(sha1_info);
// Record initialization state for downstream stubs (sha1_update/sha1_final must see this).
FUZZ_SET_ATTR_INT(sha1_info, "sha1_initialized", 1);
FUZZ_SET_ATTR_INT(sha1_info, "sha1_finalized", 0);
// Validation: sha1_info is non-null and marked initialized; ready for updates/finalization.

// Enforce that the context has been initialized and not yet finalized.
int inited = FUZZ_GET_ATTR_INT(sha1_info, "sha1_initialized");
int finalized = FUZZ_GET_ATTR_INT(sha1_info, "sha1_finalized");
if (!inited || finalized) { FUZZ_BAIL(); }

// Generate a random data buffer. FUZZ_PARAM_STR returns [1,4096] bytes.
std::string payload = FUZZ_PARAM_STR();
// Choose count in [0, payload.size()].
unsigned int maxCount = (unsigned int)payload.size();
int count = (int)(*FUZZ_PARAM(unsigned int) % (maxCount + 1));
// When count > 0, buffer must point to at least count readable bytes; when 0, we can pass nullptr.
const uint8_t *buf = (count > 0) ? reinterpret_cast<const uint8_t *>(payload.data()) : nullptr;

// Call the target function.
sha1_update(sha1_info, buf, count);

// Output the context back to the pool for further operations.
// Validation: Count is non-negative and buffer validity is enforced by construction.

// Enforce that the context has been initialized and not yet finalized.
int inited = FUZZ_GET_ATTR_INT(sha1_info, "sha1_initialized");
int finalized = FUZZ_GET_ATTR_INT(sha1_info, "sha1_finalized");
if (!inited || finalized) { FUZZ_BAIL(); }

// Prepare a 20-byte digest output buffer as required by SHA-1.
uint8_t digest[20];

// Finalize the hash and write the digest.
sha1_final(sha1_info, digest);

// Mark the context as finalized; do not return it to the pool to avoid further updates on a finalized state.
FUZZ_SET_ATTR_INT(sha1_info, "sha1_finalized", 1);
// Validation: digest buffer is at least 20 bytes; state tracking prevents use-after-finalization.

// Generate key and data as arbitrary byte sequences.
std::string keyStr = FUZZ_PARAM_STR();
std::string dataStr = FUZZ_PARAM_STR();

// Choose lengths within the provided buffers.
int keyLength = (int)(*FUZZ_PARAM(unsigned int) % (keyStr.size() + 1));
int dataLength = (int)(*FUZZ_PARAM(unsigned int) % (dataStr.size() + 1));

// Choose result length in [0,20]. Standard HMAC-SHA1 is 20; shorter lengths simulate truncation.
int resultLength = (int)(*FUZZ_PARAM(unsigned int) % 21);

// Allocate a writable buffer of at least resultLength bytes (use 20 as max).
uint8_t resultBuf[20];
uint8_t *resultPtr = resultBuf; // Non-null even if resultLength == 0

const uint8_t *keyPtr = (keyLength > 0) ? reinterpret_cast<const uint8_t *>(keyStr.data()) : nullptr;
const uint8_t *dataPtr = (dataLength > 0) ? reinterpret_cast<const uint8_t *>(dataStr.data()) : nullptr;

// Invoke the HMAC computation. Truncation behavior for resultLength < 20 is implementation-defined but typically supported.
hmac_sha1(keyPtr, keyLength, dataPtr, dataLength, resultPtr, resultLength);
// Validation: All length constraints are non-negative; output buffer capacity >= resultLength.

// Base32 encoded input; accept arbitrary bytes. Decoder should handle invalid characters by returning -1.
std::string enc = FUZZ_PARAM_STR();
const uint8_t *encoded = reinterpret_cast<const uint8_t *>(enc.c_str()); // NUL-terminated view

// Choose an output buffer size in [0, 1024]. Decoder may truncate silently if too small.
int bufSize = (int)(*FUZZ_PARAM(unsigned int) % 1025);

// Provide a non-null writable buffer even when bufSize == 0 to satisfy pointer expectations safely.
int storage = bufSize > 0 ? bufSize : 1;
std::vector<uint8_t> out((size_t)storage);
uint8_t *result = out.data();

// Call the decoder; ignore return value semantics beyond exercising paths (it may be -1 on invalid input).
(void)base32_decode(encoded, result, bufSize);
// Validation: encoded is NUL-terminated; result is writable for at least bufSize bytes (>=0) by construction.

// Arbitrary binary input to encode.
std::string dataStr = FUZZ_PARAM_STR();
int length = (int)(*FUZZ_PARAM(unsigned int) % (dataStr.size() + 1));
const uint8_t *data = (length > 0) ? reinterpret_cast<const uint8_t *>(dataStr.data()) : nullptr;

// Choose an output buffer size in [0, 2048]. Encoder may truncate silently if too small.
int bufSize = (int)(*FUZZ_PARAM(unsigned int) % 2049);
int storage = bufSize > 0 ? bufSize : 1;
std::vector<uint8_t> out((size_t)storage);
uint8_t *result = out.data();

// Invoke the encoder; the return value may be -1 on error or the number of bytes written otherwise.
(void)base32_encode(data, length, result, bufSize);
// Validation: data pointer valid for 'length' bytes when length>0; result buffer writable for bufSize bytes.

