import random
import struct
import zlib
from typing import List

MAX_TOTAL = 4096

class R(random.Random):
    pass


def _randbytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _pad_to_limit(chunks: List[bytes], limit: int) -> List[bytes]:
    total = sum(len(c) for c in chunks)
    if total > limit:
        overflow = total - limit
        # Trim from the end
        while chunks and overflow > 0:
            last = chunks[-1]
            if len(last) <= overflow:
                overflow -= len(last)
                chunks.pop()
            else:
                chunks[-1] = last[:-overflow]
                overflow = 0
    return chunks


def _mk_repeated(pattern: bytes, length: int) -> bytes:
    if not pattern or length <= 0:
        return b""
    return (pattern * (length // len(pattern) + 1))[:length]


def _mk_ascii_seq(length: int) -> bytes:
    base = (b"ABCDEFGHIJKLMNOPQRSTUVWXYZ" +
            b"abcdefghijklmnopqrstuvwxyz" +
            b"0123456789" +
            b"-_ ")
    return _mk_repeated(base, length)


def _mk_base32_chars(r: random.Random, length: int) -> bytes:
    alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
    extra = b" -\t\n\r"
    out = bytearray()
    for _ in range(length):
        if r.random() < 0.1:
            out.append(extra[r.randrange(len(extra))])
        else:
            out.append(alphabet[r.randrange(len(alphabet))])
    return bytes(out)


def _mk_sizes_near_boundaries(r: random.Random, max_len: int, block: int = 64) -> List[int]:
    sizes = set()
    base = [0, 1, 2, 3, 19, 20, 31, 32, 63, 64, 65, 127, 128, 255, 256, 511, 512, 1023, 1024]
    for b in base:
        if b <= max_len:
            sizes.add(b)
    for k in range(1, 10):
        for delta in (-2, -1, 0, 1, 2):
            val = k * block + delta
            if 0 <= val <= max_len:
                sizes.add(val)
    for _ in range(10):
        sizes.add(r.randrange(0, max_len + 1))
    return sorted(sizes)


def _compressible_blob(r: random.Random, size: int) -> bytes:
    if size <= 0:
        return b""
    parts: List[bytes] = []
    produced = 0
    while produced < size:
        remaining = size - produced
        # choose chunk in [1, min(256, remaining)] safely
        hi = min(256, remaining)
        chunk = r.randrange(1, hi + 1)
        choice = r.randrange(5)
        if choice == 0:
            seg = b"\x00" * chunk
        elif choice == 1:
            seg = _mk_repeated(b"ABCDEF", chunk)
        elif choice == 2:
            seg = _mk_ascii_seq(chunk)
        elif choice == 3:
            seg = _mk_repeated(bytes([r.randrange(256)]), chunk)
        else:
            alphabet = b"ETAOIN SHRDLU\n\t\x00"
            seg = bytes(alphabet[r.randrange(len(alphabet))] for _ in range(chunk))
        parts.append(seg)
        produced += len(seg)
    return b"".join(parts)[:size]


def _structured_packet(r: random.Random) -> bytes:
    pkt_count = r.randrange(1, 4)
    out = bytearray()
    for _ in range(pkt_count):
        tag = r.randrange(0, 0x10000)
        pay_len = r.randrange(0, 256)
        choice = r.random()
        if choice < 0.25:
            payload = _randbytes(r, pay_len)
        elif choice < 0.5:
            payload = _mk_ascii_seq(pay_len)
        elif choice < 0.75:
            payload = _compressible_blob(r, pay_len)
        else:
            payload = _mk_repeated(struct.pack('>H', tag), pay_len)
        header = struct.pack('>HH', tag, pay_len)
        crc = zlib.crc32(payload) & 0xFFFFFFFF
        out += header + payload + struct.pack('>I', crc)
    return bytes(out)


def generate(seed: int) -> bytes:
    r = R(seed)

    chunks: List[bytes] = []

    # 1) SHA-1 update payloads
    sizes = _mk_sizes_near_boundaries(r, 512)
    for sz in sizes[:10]:
        sz = max(1, sz)
        choice = r.randrange(6)
        if choice == 0:
            chunks.append(_randbytes(r, sz))
        elif choice == 1:
            chunks.append(_mk_repeated(b"\x00", sz))
        elif choice == 2:
            chunks.append(_mk_repeated(b"\xff", sz))
        elif choice == 3:
            chunks.append(_mk_ascii_seq(sz))
        elif choice == 4:
            chunks.append(_compressible_blob(r, sz))
        else:
            pattern = bytes([r.randrange(256), 0, r.randrange(256), 0])
            chunks.append(_mk_repeated(pattern, sz))

    # 2) HMAC key candidates
    key_sizes = [0, 1, 19, 20, 21, 63, 64, 65, 127, 128]
    for ks in key_sizes:
        ks2 = max(1, ks)
        mode = r.randrange(3)
        if mode == 0:
            key = _mk_repeated(b"K", ks2)
        elif mode == 1:
            key = _randbytes(r, ks2)
        else:
            key = _compressible_blob(r, ks2)
        chunks.append(key)

    # 3) HMAC data candidates
    data_sizes = [0, 1, 55, 56, 57, 63, 64, 65, 127, 128, 255, 256]
    for ds in data_sizes:
        ds2 = max(1, ds)
        pick = r.randrange(5)
        if pick == 0:
            chunks.append(_randbytes(r, ds2))
        elif pick == 1:
            chunks.append(_mk_ascii_seq(ds2))
        elif pick == 2:
            chunks.append(_compressible_blob(r, ds2))
        elif pick == 3:
            blob = _structured_packet(r)
            if len(blob) > ds2:
                blob = blob[:ds2]
            elif len(blob) < ds2:
                blob += _mk_repeated(b"\x00", ds2 - len(blob))
            chunks.append(blob if blob else b"X")
        else:
            chunks.append(_mk_repeated(b"\x00\x01\x02\x03", ds2))

    # 4) Base32 encode inputs
    b32_sizes = [0, 5, 10, 15, 20, 31, 32, 33, 63, 64, 65, 100]
    for bs in b32_sizes:
        bs2 = max(1, bs)
        if r.random() < 0.5:
            chunks.append(_randbytes(r, bs2))
        else:
            chunks.append(_mk_base32_chars(r, bs2))

    # 5) Larger blobs to push encoder truncation paths
    for big in (600, 1024, 1500):
        chunks.append(_compressible_blob(r, big))

    # Trim and join
    chunks = _pad_to_limit(chunks, MAX_TOTAL)
    data = b"".join(chunks)

    if not data:
        data = b"A"
    elif len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]

    return data
